/**
 * OneSource Docs MCP Server — stdio entry point (dev mode)
 *
 * Used by .mcp.json for local Claude Code development.
 * For npm distribution, use cli.ts instead.
 */
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { createMcpServer, VERSION } from './create-server.js';
// Resolve project root from dist/server.js -> scripts/mcp-server/dist -> project root
const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const DATA_DIR = join(__dirname, '..', 'data');
async function main() {
    console.error('[onesource-docs] Starting MCP server (dev)...');
    console.error(`[onesource-docs] Data dir: ${DATA_DIR}`);
    const { server, analytics } = createMcpServer({ data: DATA_DIR, transport: 'stdio' });
    const transport = new StdioServerTransport();
    await server.connect(transport);
    console.error('[onesource-docs] Server connected via stdio');
    analytics.trackService({
        type: 'service_start',
        service: 'onesource-docs',
        timestamp: new Date().toISOString(),
        version: VERSION,
        details: 'stdio dev mode',
    });
    process.once('SIGINT', async () => {
        console.error('[onesource-docs] Shutting down...');
        analytics.trackService({
            type: 'service_stop',
            service: 'onesource-docs',
            timestamp: new Date().toISOString(),
            version: VERSION,
        });
        analytics.stop();
        await analytics.flush();
        process.exit(0);
    });
}
main().catch((err) => {
    console.error('[onesource-docs] Fatal error:', err);
    process.exit(1);
});
